//! The app's keyed strings: apps/tasks/strings/{en,it}.toml (prefix "tasks."), generated by build.rs. The app's
//! display name is the kit's one entry (kit.app.tasks), never a key of this table.

/// The generated module: the `k` key constants and the `TABLE`.
pub mod gen {
    include!(concat!(env!("OUT_DIR"), "/strings.rs"));
}
pub use gen::{k, TABLE};

/// A key of this app's table in `lang` (pseudo-localised when `lang.pseudo`).
pub fn t(lang: oled_ui::UiLang, key: oled_sys::i18n::S) -> oled_ui::node::Text {
    lang.text(&TABLE, key)
}

/// The app's display name in `lang` (the kit's kit.app.tasks).
pub fn app_name(lang: oled_ui::UiLang) -> oled_ui::node::Text {
    lang.kit(oled_ui::strings::k::KIT_APP_TASKS)
}
